<script lang="ts">import { onMount } from 'svelte'; import { client,type Character } from '$lib/api'; import { filterRoster } from '$lib/roster'; import RosterTable from '$components/RosterTable.svelte'; let rows=$state<Character[]>([]); let search=$state(new URLSearchParams(location.search).get('search')??''); let klass=$state(new URLSearchParams(location.search).get('class')??''); let stale=$state(new URLSearchParams(location.search).get('stale')==='true'); let error=$state(''); let filtered=$derived(filterRoster(rows,{search,class:klass,stale})); let classes=$derived([...new Set(rows.map(x=>x.className))]); onMount(async()=>{try{rows=await client.roster(location.search)}catch(e){error=e instanceof Error?e.message:'Roster unavailable'}}); function update(){const q=new URLSearchParams();if(search)q.set('search',search);if(klass)q.set('class',klass);if(stale)q.set('stale','true');history.replaceState({},'',`/roster?${q}`)}</script>
<h1>Roster</h1><div class="toolbar"><input aria-label="Search roster" placeholder="Search keeper…" bind:value={search} oninput={update}/><select aria-label="Class" bind:value={klass} onchange={update}><option value="">All classes</option>{#each classes as c}<option>{c}</option>{/each}</select><label><input type="checkbox" bind:checked={stale} onchange={update}/> Stale only</label><button onclick={()=>{search='';klass='';stale=false;update()}}>Clear</button></div>{#if error}<p class="error">{error}</p>{:else if !rows.length}<p class="skeleton">Loading roster…</p>{:else}<p class="count">{filtered.length} keepers found</p><RosterTable rows={filtered}/>{/if}
